public sealed record PlantSnapshot(
    bool Connected,
    bool MotorRunning,
    double SpeedSetpoint,
    double Speed,
    double MotorTemperature,
    bool TemperatureAlarm,
    DateTimeOffset Timestamp)
{
    public static PlantSnapshot Disconnected { get; } =
        new(false, false, 0, 0, 0, false, DateTimeOffset.UtcNow);
}

/// <summary>Ergebnis eines Schreibbefehls an die Anlage.</summary>
public sealed record CommandResult(bool Success, string Message);

