using Grpc.Core;
using PlantHmi.Grpc;

namespace DataService;

/// <summary>
/// Implementiert den gRPC-Service aus plant.proto.
/// Die Basisklasse Plant.PlantBase wurde beim Build aus der .proto-Datei erzeugt.
/// </summary>
public sealed class PlantGrpcService(PlantConnection plant, ILogger<PlantGrpcService> logger)
    : Plant.PlantBase
{
    // Unary: aktuellen Zustand einmal zurückgeben
    public override Task<PlantState> GetSnapshot(SnapshotRequest request, ServerCallContext context)
    {
        return Task.FromResult(ToMessage(plant.Current));
    }

    // Server-Streaming: jede Änderung an den Client schicken, bis er die Verbindung beendet
    public override async Task WatchState(
        WatchRequest request,
        IServerStreamWriter<PlantState> responseStream,
        ServerCallContext context)
    {
        logger.LogInformation("Client {Peer} beobachtet jetzt den Anlagenzustand", context.Peer);

        try
        {
            var updates = plant.Subscribe(context.CancellationToken);
            await foreach (PlantSnapshot snapshot in updates.ReadAllAsync(context.CancellationToken))
            {
                await responseStream.WriteAsync(ToMessage(snapshot), context.CancellationToken);
            }
        }
        catch (OperationCanceledException)
        {
            // Normalfall: Der Client hat den Stream beendet
        }

        logger.LogInformation("Client {Peer} beobachtet nicht mehr", context.Peer);
    }

    public override async Task<CommandReply> SetMotor(SetMotorRequest request, ServerCallContext context)
    {
        CommandResult result = await plant.SetMotorAsync(request.Running, context.CancellationToken);
        return new CommandReply { Success = result.Success, Message = result.Message };
    }

    public override async Task<CommandReply> SetSpeedSetpoint(SetSpeedSetpointRequest request, ServerCallContext context)
    {
        CommandResult result = await plant.SetSpeedSetpointAsync(request.Rpm, context.CancellationToken);
        return new CommandReply { Success = result.Success, Message = result.Message };
    }

    // Übersetzt unser internes Modell in die gRPC-Nachricht
    private static PlantState ToMessage(PlantSnapshot s) => new()
    {
        Connected = s.Connected,
        MotorRunning = s.MotorRunning,
        SpeedSetpoint = s.SpeedSetpoint,
        Speed = s.Speed,
        MotorTemperature = s.MotorTemperature,
        TemperatureAlarm = s.TemperatureAlarm,
        TimestampUnixMs = s.Timestamp.ToUnixTimeMilliseconds(),
    };
}

