using System.Runtime.CompilerServices;
using Grpc.Core;
using Microsoft.AspNetCore.Mvc;
using PlantHmi.Grpc;
using WebApi.Models;

namespace WebApi.Controllers;

/// <summary>
/// REST-Schnittstelle für das HMI. Jede Methode übersetzt einen HTTP-Aufruf
/// in einen gRPC-Aufruf an den Datendienst.
/// </summary>
[ApiController]
[Route("api/plant")]
public class PlantController(Plant.PlantClient plant) : ControllerBase
{
    // GET /api/plant/state
    [HttpGet("state")]
    public async Task<ActionResult<PlantStateDto>> GetState(CancellationToken ct)
    {
        PlantState state = await plant.GetSnapshotAsync(new SnapshotRequest(), cancellationToken: ct);
        return PlantStateDto.FromGrpc(state);
    }

    // POST /api/plant/motor   Body: { "running": true }
    [HttpPost("motor")]
    public async Task<ActionResult<CommandResultDto>> SetMotor(SetMotorDto body, CancellationToken ct)
    {
        CommandReply reply = await plant.SetMotorAsync(
            new SetMotorRequest { Running = body.Running },
            cancellationToken: ct);
        return ToActionResult(reply);
    }

    // PUT /api/plant/speed-setpoint   Body: { "rpm": 1500 }
    [HttpPut("speed-setpoint")]
    public async Task<ActionResult<CommandResultDto>> SetSpeedSetpoint(SetSpeedSetpointDto body, CancellationToken ct)
    {
        CommandReply reply = await plant.SetSpeedSetpointAsync(
            new SetSpeedSetpointRequest { Rpm = body.Rpm },
            cancellationToken: ct);
        return ToActionResult(reply);
    }

    // GET /api/plant/stream
    // Server-Sent Events: Der Browser hält die Verbindung offen und bekommt jede Änderung.
    // Hier sieht man gut, wie der gRPC-Stream des Datendienstes "durchgereicht" wird.
    [HttpGet("stream")]
    public IResult Stream(CancellationToken ct) =>
        TypedResults.ServerSentEvents(ReadStateStream(ct), eventType: "state");

    private async IAsyncEnumerable<PlantStateDto> ReadStateStream([EnumeratorCancellation] CancellationToken ct)
    {
        using AsyncServerStreamingCall<PlantState> call = plant.WatchState(new WatchRequest(), cancellationToken: ct);

        while (await TryMoveNextAsync(call.ResponseStream, ct))
        {
            yield return PlantStateDto.FromGrpc(call.ResponseStream.Current);
        }
    }

    // Liest die nächste Nachricht aus dem gRPC-Stream. Gibt false zurück, wenn der Stream
    // endet, der Browser die Seite schließt (Cancelled) oder der Datendienst weg ist (Unavailable).
    private static async Task<bool> TryMoveNextAsync(IAsyncStreamReader<PlantState> stream, CancellationToken ct)
    {
        try
        {
            return await stream.MoveNext(ct);
        }
        catch (RpcException ex) when (ex.StatusCode is Grpc.Core.StatusCode.Cancelled or Grpc.Core.StatusCode.Unavailable)
        {
            return false;
        }
    }

    private ActionResult<CommandResultDto> ToActionResult(CommandReply reply)
    {
        var result = new CommandResultDto(reply.Success, reply.Message);

        // 200 OK, wenn die Anlage den Befehl angenommen hat, sonst 409 Conflict
        return reply.Success ? Ok(result) : Conflict(result);
    }
}
